INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('2fc1d6859b47496ab427ceec5e475d0e','叶蓬',NULL,NULL,NULL,NULL,'exact','exact','武汉（伪湖北省）','湖北','[]','["汪伪武汉绥靖公署主任→伪湖北省政府主席"]','抗日战争时期','','伪职：汪伪武汉绥靖公署主任→伪湖北省政府主席；罪行：湖北黄陂人。1939年加入汪精卫汉奸集团；1941年任伪武汉绥靖主任公署主任；1945年3月复任伪武汉绥靖主任公署主任兼伪湖北省政府主席；垄断食盐、贩卖鸦片、搜刮民财；结局：1946年10月1日被捕；同年冬经国民政府高等法院判处死刑，就地枪决','[]','2026-09-09 03:34:24.846402','2026-09-09 03:34:24.846402');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('4b3ca21ce5e54ead831d6d3b0ffb95d0','张仁蠡',NULL,NULL,NULL,NULL,'exact','exact','武汉（伪武汉市政府）','北京','[]','["伪武汉特别市政府市长"]','抗日战争时期','','伪职：伪武汉特别市政府市长；罪行：张之洞第十三子。1935年任伪冀东防共自治政府民政厅长；1939年4月任伪武汉特别市政府首任市长；结局：1951年以汉奸罪在北京被判处死刑','[]','2026-09-09 03:34:24.846409','2026-09-09 03:34:24.846409');
