INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('6661468a9a9540f08ee37efd74a71e13','王绍武',NULL,NULL,NULL,NULL,'exact','exact','济宁（兖州）','','["王梅芳", "王歪头"]','["伪宁阳县知事（1939）→伪兖济道道尹（1942—1945）"]','抗日战争时期','','伪职：伪宁阳县知事（1939）→伪兖济道道尹（1942—1945）；罪行：滋阳（今兖州）人。原为土匪武装头目，1938年率部投降日军。任宁阳伪县长期间祸害宁阳四年；1942年升任兖济道道尹，管辖济宁、宁阳、曲阜、滋阳等十余县伪政权。推行保甲连坐，强征粮食壮丁；配合日军扫荡泰西、尼山抗日根据地；大肆抓捕地下党员与抗日干部。打死打伤我军民数百人；结局：1945年日本投降后投靠国民党；解放战争后期被俘，镇反运动中被判处死刑执行枪决','[]','2026-09-09 03:34:24.847644','2026-09-09 03:34:24.847644');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('adfec3c1420746b6897b93bd2254281f','吴廷玉',NULL,NULL,NULL,NULL,'exact','exact','曲阜','','[]','["曲阜县维持会会长"]','抗日战争时期','','伪职：曲阜县维持会会长；罪行：曲阜城大地主、大资本家。1938年1月4日晨，制作日本膏药旗迎接日军大部队进城。日军进城后随即任命其为“维持会”会长，并组织伪曲阜县公署、伪曲阜县警备队。协助日军搜刮城内物资，逼迫百姓办理良民证；拉拢乡绅投敌，在各乡镇建立伪保甲体系；结局：抗战胜利后被逮捕，以汉奸罪判刑，刑满后回乡','[]','2026-09-09 03:34:24.847658','2026-09-09 03:34:24.847658');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('b85ca24ac1224fa89a167242d3189b84','常之英',NULL,NULL,NULL,NULL,'exact','exact','济宁','北京','[]','["伪山东省公署总务厅长→伪潍县知事→伪莱潍道尹→伪登州道尹→伪济南道道尹→伪青州特别区行政长官"]','抗日战争时期','','伪职：伪山东省公署总务厅长→伪潍县知事→伪莱潍道尹→伪登州道尹→伪济南道道尹→伪青州特别区行政长官；罪行：济宁人。1915年北京政府陆军参谋本部测量学校毕业。1938年5月投降日军。先后任伪山东省公署总务厅长、伪潍县知事、伪莱潍道尹、伪登州道尹、伪济南道道尹等职；结局：1946年被国民党山东省高等法院以汉奸罪逮捕，判处有期徒刑7年','[]','2026-09-09 03:34:24.847666','2026-09-09 03:34:24.847666');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d316fdc3c24446b69e8148343530bd4c','程镕',NULL,NULL,NULL,NULL,'exact','exact','济宁','山东','[]','["伪兖济道道尹（继任）"]','抗日战争时期','','伪职：伪兖济道道尹（继任）；罪行：1944年4月15日，伪山东省政府发出训令，伪兖济道道尹程镕代理济南市长','[]','2026-09-09 03:34:24.847672','2026-09-09 03:34:24.847672');
