INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('356be0d136b647769ffb682e55d13080','刘本功',NULL,NULL,NULL,NULL,'exact','exact','汶上县（原济宁县）','山东','["刘建勋", "活阎王", "刘半湖"]','["伪郓城县维持会会长→伪郓城县县长（1939—1945）→国民党鲁西南剿匪总司令"]','抗日战争时期','','伪职：伪郓城县维持会会长→伪郓城县县长（1939—1945）→国民党鲁西南剿匪总司令；罪行：汶上县康驿东刘庄人。韩复榘旧部特务连长。1939年1月投靠日军，任伪郓城县长，统治郓城长达七年。兵力2000余人。配合日军九二七大扫荡，屠杀抗日军民两千人以上；强征数万百姓修筑金堤封锁沟；焚烧村庄、劫掠湖区。1942年以私通八路罪名活埋潘渡村皮行经理李殿阁；1943—1944年强征1437名青壮年赴日本北海道挖煤，仅131人生还；结局：日军投降后投靠国民党，驻守济宁。1946年济宁解放逃至济南，被国民党山东省长王耀武以恶贯郓城、失守济宁等罪处决','[]','2026-09-09 03:34:24.847683','2026-09-09 03:34:24.847683');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('5531c78b666e41a29e310259a7e8fdca','陈德山',NULL,NULL,NULL,NULL,'exact','exact','汶上县','','["小梁子"]','["伪大队长（刘本功部）"]','抗日战争时期','','伪职：伪大队长（刘本功部）；罪行：汶上县康驿人。早年在戏班唱戏，1941年以蜀山湖为据点拉帮为匪。1942年投靠刘本功，任伪大队长，活动汶上、济宁、宁阳交界。到处劫掠，捕杀民兵、农会干部；多次随伪军下乡“清乡”。抗战胜利后变本加厉，配合国民党84师疯狂袭击屠杀共产党干部和群众，两三年间杀害干部群众几百人；结局：抗战胜利后投靠国民党。1951年2月在哈尔滨被抓获，押解济宁后处决','[]','2026-09-09 03:34:24.847691','2026-09-09 03:34:24.847691');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('f9936452cea745d19f2720a68827fd9f','阎先恕',NULL,NULL,NULL,NULL,'exact','exact','嘉祥县','','[]','["嘉祥县伪三区区长→嘉祥县自卫团团长"]','抗日战争时期','','伪职：嘉祥县伪三区区长→嘉祥县自卫团团长；罪行：嘉祥县纸坊镇阎村人。1938年3月任嘉祥县伪三区区长。1940年成立新民会三区分会，推行“强化治安政策”。1942年组建百余人的自卫团自任团长。1943年被国民党改编为鲁西专署保安第十旅任旅长，近2000人。率部屠杀抗日军民和群众，抢劫抗日政府粮食物资。自1939年至1947年共杀害308人；结局：1947年3月9日被冀鲁豫七分区参谋长杨昆部击毙','[]','2026-09-09 03:34:24.847697','2026-09-09 03:34:24.847697');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('4df24a6c61f84908b51919247ff0250f','冯德志',NULL,NULL,NULL,NULL,'exact','exact','泗水县','','[]','["泗水县伪警察所特务系长"]','抗日战争时期','','伪职：泗水县伪警察所特务系长；罪行：泗水人。旧政权巡官，1939年返回泗水投靠日伪警务局，掌管特务系，直接归兖州日本宪兵指挥。建立情报网，收买乡村密探；搜捕地下党组织，抓捕杀害多名抗日干部；策划偷袭抗日人员驻地；结局：泗水解放后被俘，公审后枪毙','[]','2026-09-09 03:34:24.847704','2026-09-09 03:34:24.847704');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('e938921c23764029ac336ecf38b1822c','张显荣',NULL,NULL,NULL,NULL,'exact','exact','泗水县','','[]','["泗水皇协军司令"]','抗日战争时期','','伪职：泗水皇协军司令；罪行：泗水张庄人。原本拉起武装号称抗日，1942年经受日伪威逼利诱，率千余人队伍投降日军，出任皇协军司令，盘踞泗南山区。调转枪口攻打尼山根据地；出卖地下交通站；在山区设立据点，勒索周边村庄；结局：1944年八路军攻克张庄据点，张显荣被击毙','[]','2026-09-09 03:34:24.847709','2026-09-09 03:34:24.847709');
