INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('9de2a7b39ab541679eccad51e4fe3b7a','丁默邨',NULL,NULL,NULL,NULL,'exact','exact','常德','浙江','["丁默村"]','["汪伪中央常委、社会部长、交通部长、浙江省主席、汪伪特工总部（76号）主任"]','抗日战争时期','','伪职：汪伪中央常委、社会部长、交通部长、浙江省主席、汪伪特工总部（76号）主任；罪行：常德城区大高山街人。早年加入共青团，后叛变投靠国民党，再投靠汪伪政权。任汪伪特工总部主任期间，制造血案数千起，人称“丁屠夫”。是电影《色戒》中男主角的原型；结局：1945年9月被国民政府逮捕；1946年11月被提起公诉；1947年2月首都最高法院特种刑事庭判处死刑；1947年7月5日在苏州狮子口监狱刑场被执行枪决','[]','2026-09-09 03:34:24.848006','2026-09-09 03:34:24.848006');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('c7a0b0d997414bf786b2f9ff1f50199b','彭叫驴子',NULL,NULL,NULL,NULL,'exact','exact','常德会战','天津','["彭大驴子", "彭春荣"]','["“和平救国军三湘特遣纵队”司令（湘西惯匪）"]','抗日战争时期','','伪职：“和平救国军三湘特遣纵队”司令（湘西惯匪）；罪行：湘西惯匪。1941年投奔汪伪政权，大汉奸周佛海亲自委以“和平救国军三湘特遣纵队司令”官衔。1943年常德会战中为日军第11军带路，指出哪条河可以徒涉、哪座山有秘密小路。率4000人沿山间穿插，突袭预10师战斗指挥所。常德民间流传“千刀万剐彭叫驴子”；结局：众说纷纭。一说改名换姓毁容隐匿天津，1948年被军警捕获，以汉奸罪处死','[]','2026-09-09 03:34:24.848018','2026-09-09 03:34:24.848018');
