INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('7675452d3bad4516a2171835446ac784','曹明阵',NULL,NULL,NULL,NULL,'exact','exact','益阳县','湖南','[]','["益阳县团防局局长、益阳保安团长、常德桃源益阳联防主任"]','抗日战争时期','','伪职：益阳县团防局局长、益阳保安团长、常德桃源益阳联防主任；罪行：益阳县沧水铺四方山人。1926年起镇压革命，马日事变后卷土重来重掌县团防局。1930年率保安团队恭迎湖南省政府主席何键。抗战爆发后寻机投靠日本人，退隐沧水铺一带，耍阴谋放暗枪，与抗日组织作对。1938年率部拦路抢劫国军43师武器弹药；结局：1939年被国军43师诱捕押送长沙；同年4月湖南省高等法院以抢劫国军枪支、破坏抗战等罪名判处死刑；4月16日在长沙小吴门外被枪决','[]','2026-09-09 03:34:24.849662','2026-09-09 03:34:24.849662');
