INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('f0134c9c66e24985904d104f11d812ba','罗君强',NULL,NULL,NULL,NULL,'exact','exact','湘乡县（今娄底市娄星区西阳乡白鹭湾）','上海','[]','["汪伪政权中央执行委员会委员、中央党部副秘书长、边疆委员会委员长、司法行政部长、安徽省省长、伪上海市政府秘书长等"]','抗日战争时期','','伪职：汪伪政权中央执行委员会委员、中央党部副秘书长、边疆委员会委员长、司法行政部长、安徽省省长、伪上海市政府秘书长等；罪行：1939年春在香港投敌；同年8月参加汪伪国民党六大，被指派为中央执行委员会委员兼中央党部副秘书长；历任伪边疆委员会委员长、伪司法行政部部长、伪中央税警总团中将总团长、伪安徽省省长兼伪蚌埠绥靖公署主任、伪上海市政府秘书长等职；结局：1945年日本投降后曾被蒋介石政府任命为上海行动总队副总指挥；1947年3月被国民政府以汉奸罪判处无期徒刑；新中国成立后监押于上海提篮桥监狱；1970年2月22日病逝','[]','2026-09-09 03:34:24.850178','2026-09-09 03:34:24.850178');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('eb8173e8f81b4c7fb92bb1ad32687aee','张岚峰',NULL,NULL,NULL,NULL,'exact','exact','商丘（豫东）','河南','["张岚锋"]','["伪豫东招抚使→伪和平救国军第1军中将军长→伪第2集团军总司令→伪第4方面军中将总司令"]','抗日战争时期','','伪职：伪豫东招抚使→伪和平救国军第1军中将军长→伪第2集团军总司令→伪第4方面军中将总司令；罪行：柘城县人，原西北军将领，曾留学日本陆军士官学校。1937年回乡组建“柘城维持会”，公然投靠日寇。1938年在商丘设“豫东招抚使公署”，沿陇海路招募土匪流民，很快聚集4个军近1.8万人。1943年任伪第2集团军总司令，1944年升伪第4方面军中将总司令，麾下扩充至9万余人，是河南省伪军中规模最大的力量；结局：1952年被人民政府处决','[]','2026-09-09 03:34:24.850601','2026-09-09 03:34:24.850601');
