INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('5262fb67632240bcb710c74146d8b74b','扈全禄',NULL,NULL,NULL,NULL,'exact','exact','鹤壁（浚县/淇县/汤阴）','河南','[]','["伪河南剿匪总司令"]','抗日战争时期','','伪职：伪河南剿匪总司令；罪行：原为豫北老牌匪首，抗战爆发后反复摇摆，最终投降日军，被委任伪河南剿匪总司令。部队活动于淇县、浚县、汤阴一带，配合日军扫荡，捕杀抗日军民，劫掠乡村。其主力多次遭八路军打击，屡次溃败又死灰复燃；结局：抗战结束后依附国民党顽军继续作恶，新乡解放时被俘，在狱中畏罪自缢','[]','2026-09-09 03:34:24.856676','2026-09-09 03:34:24.856676');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('a71a88d00b88420b96cdaac183b1648a','孙步月',NULL,NULL,NULL,NULL,'exact','exact','鹤壁（浚县）','','[]','["豫北剿共副司令、浚滑内黄3县边区反共自卫团团长"]','抗日战争时期','','伪职：豫北剿共副司令、浚滑内黄3县边区反共自卫团团长；罪行：1938年秋投靠日寇，组建浚、滑、内黄3县边区反共自卫团，被日寇封为“豫北剿共副司令”。以郭小寨为中心构建大型伪军据点，多次配合日军对沙区抗日根据地进行扫荡。先后杀害革命干部及群众420余人，烧毁房屋3000余间；结局：1945年4月，冀鲁豫军区发起讨伐战斗，经三昼夜激战，其主力被八路军彻底歼灭，孙步月本人在战斗中被俘，随后依法惩处。善堂镇烈士纪念碑前雕有双手反缚、双腿下跪、背插亡命旗石像，即孙步月','[]','2026-09-09 03:34:24.856687','2026-09-09 03:34:24.856687');
