INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d7b0713dbb6b423086736acc47747116','宋仲佳',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区','','[]','["伪宜昌县县长"]','抗日战争时期','','伪职：伪宜昌县县长；罪行：1941年2月任伪县政筹备处处长，不久代理伪宜昌县县长，同年3月30日成立伪宜昌县政府。任职不足三个月，一次坐包车出大南门哨卡时未向日军行礼，被日本兵打了几个耳光并辱骂，回公馆后即死；结局：1941年被日本兵殴打后死亡','[]','2026-09-09 03:34:24.869347','2026-09-09 03:34:24.869347');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d47b302e156a469d811a6deeceb48d94','王虚原',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区','','[]','["伪宜昌县县长（后任）"]','抗日战争时期','','伪职：伪宜昌县县长（后任）；罪行：继宋仲佳之后任伪宜昌县长。1941年9月27日，国军飞行员张惕勤、汤厚涟、梁文华驾驶苏制SB-Ⅱ轰炸机投敌，曾在宜昌铁路坝短暂停留，王虚原与日军一同前往迎接；结局：抗战胜利后以“没有血债”为由被判无期徒刑，不久被其警官儿子王汝功以患病为由保释','[]','2026-09-09 03:34:24.869354','2026-09-09 03:34:24.869354');
