INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('eaaf966f8bed4ee3a35f5944dec2d80c','汤炳如',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区','','[]','["日伪乡长、维持会长、情报所长、密侦大队长"]','抗日战争时期','','伪职：日伪乡长、维持会长、情报所长、密侦大队长；罪行：晓溪塔郭家冲汤家湾人，出身地主，人称汤三爷。1940年6月宜昌沦陷后投敌，先后任日伪乡长、维持会长、合作社事务员、情报所长、密侦大队长等职。在梅子垭设关卡，与日寇一起盘查过卡中国人，凡过卡者由日本哨兵先问汤“他们中国人的明白？”汤若点头即能过，若歪头即被当场杀死。兼任合作社事务员，大量税款流入其腰包。1941年至1943年间多次烧杀抢劫：烧毁张开余、胡少云、徐大金等人的房屋并杀人；指认龙书齐为情报员，被日军用狼狗活活咬死；杀害杨宏义一家四口','[]','2026-09-09 03:34:24.869392','2026-09-09 03:34:24.869392');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('50be26fa66c54e05b6e7f1b6e37e6197','杨介轩',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区/宜都','','["杨大震"]','["宜都江北维持总会会长、宜昌第四区公署区长"]','抗日战争时期','','伪职：宜都江北维持总会会长、宜昌第四区公署区长；罪行：宜都白洋区小冲口人（今属枝江市），以烧窑为生。1940年日军侵占宜都江北后，先在石宝山设维持总会任会长，下辖顾家店、张家店等多个分会；后在小冲口设维持总会仍任会长，统辖云池、古老背等地分会。1941年1月任紫荆岭维持会联合会会长，同年8月任宜昌第四区公署区长。以通国军等借口抓捕敲诈民众；强行侵占郑旭轩等人田地，强买张刘氏等人土地79亩；参与紫荆岭酒精厂设立，低价强收粮食1.82万石提炼酒精；为日军强征物资并强征民夫4220名；1944年8月杀害国民党第六战区情报人员叶子明，指使章元干暗杀区长吴家修；结局：抗战胜利后被移交高等法院审判，后越狱潜逃；1951年被宜都县人民政府缉拿归案并处决','[]','2026-09-09 03:34:24.869398','2026-09-09 03:34:24.869398');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('cdbcafc9de6a403ca19ec7cabf2a7281','古天明',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区','','["古霸天"]','["大汉奸（开洋行、放高利贷）"]','抗日战争时期','','伪职：大汉奸（开洋行、放高利贷）；罪行：开洋行，放高利贷，勾结日寇，欺压百姓，被人称为“古霸天”。是宜昌臭名昭著的大汉奸；结局：待考（曾遭暗杀）','[]','2026-09-09 03:34:24.869404','2026-09-09 03:34:24.869404');
